// GENERATED by scripts/build-assets.mjs — do not edit by hand.
// Embeds the static assets so the Worker can be deployed as a single file (no assets binding).
export const STATIC_MAP: Record<string, { type: string; body: string; isBinary?: boolean }> = {
  "/favicon.ico": { type: "image/x-icon", body: "", isBinary: true },
  "/robots.txt": { type: "text/plain; charset=utf-8", body: "User-agent: *\nAllow: /\n" },
  "/css/site.css": { type: "text/css; charset=utf-8", body: "/* Graf minimal styles */\n:root {\n  --ink: #1a1a1a;\n  --muted: #6b7280;\n  --line: #e5e7eb;\n  --accent: #111827;\n  --radius: 10px;\n}\n* { box-sizing: border-box; }\nhtml { -webkit-text-size-adjust: 100%; }\nbody {\n  margin: 0;\n  font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"PingFang SC\", \"Hiragino Sans GB\", \"Microsoft YaHei\", Roboto, Helvetica, Arial, sans-serif;\n  color: var(--ink);\n  background: #fff;\n  line-height: 1.7;\n}\n.wrap { max-width: 760px; margin: 0 auto; padding: 0 20px; }\n.center { text-align: center; padding-top: 15vh; }\n.brand { display: inline-block; margin: 26px 0 6px; font-weight: 700; letter-spacing: .02em; text-decoration: none; color: var(--ink); }\n\n/* editor */\n.editor-page { padding-top: 30px; }\n.editor textarea { width: 100%; min-height: 46vh; font-size: 16px; line-height: 1.8; border: 0; outline: none; resize: vertical; font-family: inherit; }\n.editor input[type=\"text\"] { display: block; width: 100%; border: 0; outline: none; }\n.editor input[name=\"title\"] { font-size: 34px; font-weight: 700; margin: 10px 0 4px; }\n.editor input[name=\"author\"] { font-size: 14px; color: var(--muted); margin-bottom: 18px; }\n.editor textarea::placeholder { color: #c0c4cc; }\n.row-end { display: flex; justify-content: flex-end; gap: 8px; align-items: center; }\n.row { display: flex; gap: 8px; margin: 14px 0; align-items: center; }\n.inline { display: inline-block; margin: 0; }\n.btn {\n  display: inline-block; padding: 9px 22px; border: 1px solid var(--ink); border-radius: 999px;\n  background: transparent; color: var(--ink); cursor: pointer; font-size: 14px; text-decoration: none; font-family: inherit;\n  transition: background .15s, color .15s;\n}\n.btn:hover { background: var(--ink); color: #fff; }\n.btn-sm { padding: 4px 12px; font-size: 13px; }\n.btn.ghost { border-color: var(--line); color: var(--muted); }\n.btn.danger { border-color: #dc2626; color: #dc2626; }\n.btn.danger:hover { background: #dc2626; color: #fff; }\n.back { color: var(--muted); text-decoration: none; font-size: 13px; }\n.alert { background: #fef2f2; color: #b91c1c; border: 1px solid #fecaca; padding: 10px 14px; border-radius: var(--radius); margin: 10px 0; }\n\n/* note view */\n.note-wrap { padding-bottom: 90px; }\n.post-head { margin: 30px 0 6px; }\n.post-head h1 { font-size: 32px; line-height: 1.3; margin: 0 0 6px; }\n.post-head .meta { color: var(--muted); font-size: 13px; margin-bottom: 26px; }\n.edit-bar { display: flex; justify-content: flex-end; gap: 12px; margin: 18px 0 0; font-size: 13px; align-items: center; }\n.linklike { background: none; border: 0; color: var(--muted); cursor: pointer; text-decoration: underline; font-size: 13px; }\n\n.markdown-content { font-size: 17px; overflow-wrap: break-word; }\n.markdown-content h1, .markdown-content h2, .markdown-content h3, .markdown-content h4 { line-height: 1.35; margin: 1.4em 0 .5em; }\n.markdown-content h1 { font-size: 1.7em; }\n.markdown-content h2 { font-size: 1.45em; }\n.markdown-content h3 { font-size: 1.25em; }\n.markdown-content p { margin: 1em 0; }\n.markdown-content a { color: var(--accent); }\n.markdown-content img { max-width: 100%; height: auto; border-radius: 6px; }\n.markdown-content pre { background: #f6f7f8; border: 1px solid var(--line); padding: 14px 16px; border-radius: var(--radius); overflow-x: auto; font-size: 14px; line-height: 1.6; }\n.markdown-content code { font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-size: .9em; background: #f1f2f4; padding: 2px 5px; border-radius: 4px; }\n.markdown-content pre code { background: none; padding: 0; }\n.markdown-content blockquote { margin: 1em 0; padding-left: 1em; border-left: 3px solid var(--line); color: #444; }\n.markdown-content ul, .markdown-content ol { padding-left: 1.6em; }\n.markdown-content li { margin: .35em 0; }\n.markdown-content table { border-collapse: collapse; margin: 1em 0; width: 100%; font-size: 15px; }\n.markdown-content th, .markdown-content td { border: 1px solid var(--line); padding: 7px 11px; text-align: left; }\n.markdown-content hr { border: 0; border-top: 1px solid var(--line); margin: 2em 0; }\n.markdown-content iframe.graf-embed { max-width: 100%; border-radius: 8px; display: block; margin: 1em 0; }\n.f404 { font-size: 90px; margin: 0; line-height: 1; }\n\n/* admin */\n.admin-nav { display: flex; gap: 18px; align-items: center; padding: 18px 20px; border-bottom: 1px solid var(--line); margin-bottom: 18px; flex-wrap: wrap; }\n.admin-nav a { text-decoration: none; color: var(--muted); font-size: 14px; }\n.admin-nav a.on { color: var(--ink); font-weight: 700; border-bottom: 2px solid var(--ink); }\n.admin-nav form { margin-left: auto; }\n.admin-main h1 { font-size: 24px; }\n.admin-main h2 { font-size: 18px; margin-top: 26px; }\n.stat-row { display: flex; gap: 14px; margin: 12px 0 18px; flex-wrap: wrap; }\n.stat { border: 1px solid var(--line); border-radius: var(--radius); padding: 14px 22px; min-width: 110px; }\n.stat b { display: block; font-size: 26px; }\n.stat span { color: var(--muted); font-size: 12px; }\n.table { width: 100%; border-collapse: collapse; font-size: 13px; margin: 12px 0; }\n.table th, .table td { border-bottom: 1px solid var(--line); padding: 8px 10px; text-align: left; vertical-align: top; }\n.table th { color: var(--muted); font-weight: 600; white-space: nowrap; }\n.table small { color: var(--muted); }\n.narrow { max-width: 420px; }\n.stack { display: flex; flex-direction: column; gap: 12px; margin-top: 20px; }\n.stack input, .row input[type=\"search\"], .row input[type=\"text\"], form.stack input { border: 1px solid var(--line); border-radius: 8px; padding: 10px 12px; font-size: 14px; font-family: inherit; }\n.admin input, .admin input[type=\"text\"], .admin input[type=\"password\"], .admin input[type=\"search\"] { border: 1px solid var(--line); border-radius: 8px; padding: 9px 11px; font-size: 14px; font-family: inherit; }\npre { white-space: pre-wrap; word-break: break-word; }\n\n@media (max-width: 640px) {\n  .post-head h1 { font-size: 25px; }\n  .markdown-content { font-size: 16px; }\n}\n\n/* novel mode */\n.book-list, .chapter-list { list-style: none; padding: 0; }\n.book-list li, .chapter-list li { padding: 12px 0; border-bottom: 1px solid var(--line); }\n.book-title { font-size: 1.1em; font-weight: 700; text-decoration: none; color: var(--ink); }\n.small { font-size: 12px; }\n.book-nav { margin: 34px 0 0; padding-top: 18px; border-top: 1px solid var(--line); }\n.book-nav .row { justify-content: space-between; }\n\n\n.dl-note { justify-content: space-between; margin: 14px auto 0; }\n[data-graf-count] { display:block; text-align:right; color: var(--muted); font-size: 12px; margin: 2px 0 8px; }\n\n" },
  "/js/editor.js": { type: "application/javascript; charset=utf-8", body: "// Graf editor autogrow\ndocument.addEventListener(\"DOMContentLoaded\", function () {\n  var ta = document.querySelector(\".editor textarea[name=content]\");\n  if (!ta) return;\n  function grow() {\n    ta.style.height = \"auto\";\n    ta.style.height = ta.scrollHeight + \"px\";\n  }\n  ta.addEventListener(\"input\", grow);\n  grow();\n});\n\n// --- Graf 作者工具：自动保存草稿 + 字数统计（仅新文章页，编辑已有文章不覆盖） ---\n(function () {\n  var form = document.querySelector(\"form.editor\");\n  var ta = form ? form.querySelector(\"textarea[name=content]\") : null;\n  if (!form || !ta) return;\n  var isNew = (form.getAttribute(\"action\") || \"\").indexOf(\"edit\") === -1;\n  var KEY = \"graf-draft-v1\";\n  var timer = null;\n\n  function words() {\n    var v = ta.value.trim();\n    return v ? v.length : 0; // 中文按字符计数\n  }\n  function updateCount() {\n    var el = document.querySelector(\"[data-graf-count]\");\n    if (el) el.textContent = \"字数 \" + words();\n  }\n  function save() {\n    try { localStorage.setItem(KEY, JSON.stringify({ at: Date.now(), text: ta.value, title: (form.querySelector(\"input[name=title]\") || {}).value || \"\" })); } catch (e) {}\n  }\n  function clearDraft() {\n    try { localStorage.removeItem(KEY); } catch (e) {}\n    var hint = document.querySelector(\"[data-graf-draft]\");\n    if (hint) hint.remove();\n  }\n\n  if (isNew) {\n    ta.addEventListener(\"input\", function () {\n      updateCount();\n      clearTimeout(timer);\n      timer = setTimeout(save, 600);\n    });\n    var saved = null;\n    try { saved = JSON.parse(localStorage.getItem(KEY) || \"null\"); } catch (e) {}\n    if (saved && saved.text && saved.text !== ta.value) {\n      var bar = document.createElement(\"p\");\n      bar.className = \"row wrap dl-note\";\n      bar.setAttribute(\"data-graf-draft\", \"1\");\n      var restored = false;\n      var fill = document.createElement(\"button\");\n      fill.type = \"button\";\n      fill.className = \"btn btn-sm\";\n      fill.textContent = \"恢复上次草稿（\" + words() + \" 字）\";\n      fill.onclick = function () {\n        if (restored) return;\n        if (ta.value && !window.confirm(\"当前内容将被草稿覆盖，确定恢复？\")) return;\n        ta.value = saved.text || \"\";\n        var t = form.querySelector(\"input[name=title]\");\n        if (t && saved.title) t.value = saved.title;\n        ta.dispatchEvent(new Event(\"input\"));\n        restored = true;\n        fill.textContent = \"已恢复\";\n      };\n      var rm = document.createElement(\"button\");\n      rm.type = \"button\";\n      rm.className = \"btn btn-sm ghost\";\n      rm.textContent = \"丢弃草稿\";\n      rm.onclick = function () { clearDraft(); };\n      bar.appendChild(fill);\n      bar.appendChild(rm);\n      form.parentNode.insertBefore(bar, form);\n    }\n  } else {\n    var el = document.createElement(\"span\");\n    el.className = \"meta\";\n    el.setAttribute(\"data-graf-count\", \"1\");\n    form.parentNode.insertBefore(el, form);\n  }\n  updateCount();\n})();\n\n" },
  "/js/site.js": { type: "application/javascript; charset=utf-8", body: "// Graf note-page helpers\ndocument.addEventListener(\"DOMContentLoaded\", function () {\n  var copyBtn = document.querySelector(\"[data-copy-edit]\");\n  if (copyBtn) {\n    copyBtn.addEventListener(\"click\", function () {\n      var url = copyBtn.getAttribute(\"data-url\") || \"\";\n      var done = function () {\n        var old = copyBtn.textContent;\n        copyBtn.textContent = \"Copied!\";\n        setTimeout(function () { copyBtn.textContent = old; }, 1600);\n      };\n      if (navigator.clipboard && window.isSecureContext) {\n        navigator.clipboard.writeText(url).then(done, function () { fallback(url, done); });\n      } else {\n        fallback(url, done);\n      }\n    });\n  }\n  function fallback(url, done) {\n    var ta = document.createElement(\"textarea\");\n    ta.value = url;\n    ta.style.position = \"fixed\";\n    ta.style.opacity = \"0\";\n    document.body.appendChild(ta);\n    ta.select();\n    try { document.execCommand(\"copy\"); } catch (e) {}\n    document.body.removeChild(ta);\n    done();\n  }\n});\n" },
  "/js/paranote.js": { type: "application/javascript; charset=utf-8", body: "(function () {\n  // 支持油猴脚本注入的配置\n  const config = window.__paranoteConfig || {};\n  const script = document.currentScript || {};\n\n  console.log(\"ParaNote: Script loaded\", config);\n\n  const siteId = config.siteId || script.dataset?.siteId || \"default-site\";\n  \n  // Allow explicit empty string for relative paths\n  let apiBase = config.apiBase;\n  if (apiBase === undefined) {\n      apiBase = script.getAttribute?.(\"data-api-base\");\n      if (apiBase === null) {\n          apiBase = (script.src && new URL(script.src).origin.replace(/\\/$/, \"\")) || \"\";\n      }\n  }\n  \n  // 使用油猴的 GM_xmlhttpRequest 或普通 fetch\n  // 油猴脚本会注入 window.__paranoteRequest\n  async function apiRequest(url, options = {}) {\n    // 如果有油猴注入的请求函数，使用它（绑过 CSP）\n    if (window.__paranoteRequest) {\n      return window.__paranoteRequest(url, options);\n    }\n    // 否则使用普通 fetch\n    const res = await fetch(url, options);\n    return res.json();\n  }\n  \n  async function apiPost(url, data) {\n    const headers = { \"Content-Type\": \"application/json\" };\n    if (typeof window !== \"undefined\" && window.PARANOTE_TOKEN) {\n      headers[\"X-Paranote-Token\"] = window.PARANOTE_TOKEN;\n    }\n    return apiRequest(url, {\n      method: \"POST\",\n      headers,\n      body: JSON.stringify(data),\n    });\n  }\n  \n  async function apiGet(url) {\n    return apiRequest(url, { method: \"GET\" });\n  }\n  \n  async function apiDelete(url, data) {\n    const headers = { \"Content-Type\": \"application/json\" };\n    if (typeof window !== \"undefined\" && window.PARANOTE_TOKEN) {\n      headers[\"X-Paranote-Token\"] = window.PARANOTE_TOKEN;\n    }\n    return apiRequest(url, {\n      method: \"DELETE\",\n      headers,\n      body: JSON.stringify(data),\n    });\n  }\n\n  function init() {\n      // 支持多个 root（知乎多个回答）\n      const roots = document.querySelectorAll(\"[data-na-root]\");\n      console.log(\"ParaNote: Checking roots...\", roots.length);\n      \n      if (roots.length === 0) {\n          console.log(\"ParaNote: Root not found, waiting for DOMContentLoaded...\");\n          if (document.readyState === \"loading\") {\n              document.addEventListener(\"DOMContentLoaded\", init);\n          } else {\n              console.warn(\"ParaNote: DOM loaded but root still missing\");\n          }\n          return;\n      }\n      \n      // 初始化每个 root\n      roots.forEach((root, index) => initRoot(root, index));\n  }\n  \n  function initRoot(root, rootIndex) {\n      // Check if already initialized\n      if (root.dataset.paranoteInitialized) {\n          console.log(`ParaNote: Root ${rootIndex} already initialized`);\n          return;\n      }\n      root.dataset.paranoteInitialized = \"true\";\n\n      const workId = root.dataset.workId || \"default-work\";\n      const chapterId = root.dataset.chapterId || root.dataset.ChapterId || \"default-chapter\";\n      const paras = root.querySelectorAll(\"p\");\n\n      console.log(`ParaNote: Root ${rootIndex} - Found ${paras.length} paragraphs, chapterId: ${chapterId}`);\n\n      if (!paras.length) {\n          console.warn(\"ParaNote: No paragraphs found in root\");\n          return;\n      }\n      \n      let currentParaIndex = null;\n\n      // 检测是否为移动端\n      const isMobile = window.innerWidth <= 768 || \"ontouchstart\" in window;\n\n      // 创建遮罩层（移动端用）\n      const overlay = document.createElement(\"div\");\n      overlay.className = \"na-overlay\";\n      Object.assign(overlay.style, {\n        position: \"fixed\",\n        top: \"0\",\n        left: \"0\",\n        right: \"0\",\n        bottom: \"0\",\n        background: \"rgba(0,0,0,0.5)\",\n        zIndex: 99998,\n        display: \"none\",\n      });\n      overlay.onclick = function () {\n        sidebar.container.style.display = \"none\";\n        overlay.style.display = \"none\";\n        if (isMobile) document.body.style.overflow = \"\";\n        \n        if (currentParaIndex !== null && paras[currentParaIndex]) {\n            paras[currentParaIndex].style.textDecoration = \"none\";\n            paras[currentParaIndex].style.background = \"transparent\";\n            currentParaIndex = null;\n            updateCommentCounts();\n        }\n      };\n      document.body.appendChild(overlay);\n\n      // 创建右侧评论面板\n      const sidebar = createSidebar();\n      document.body.appendChild(sidebar.container);\n\n      function createSidebar() {\n        const container = document.createElement(\"div\");\n        container.className = \"na-sidebar\";\n        \n        // Hypothesis 风格配色\n        const styles = {\n            bg: \"#f7f7f7\",\n            cardBg: \"#ffffff\",\n            text: \"#333\",\n            meta: \"#707070\",\n            border: \"#dbdbdb\",\n            primary: \"#bd1c2b\", // Hypothesis 红色\n            shadow: \"0 4px 12px rgba(0,0,0,0.15)\"\n        };\n\n        // 注入 Keyframe 动画\n        const styleTag = document.createElement('style');\n        styleTag.textContent = `\n            @keyframes slideUp { from { transform: translateY(100%); } to { transform: translateY(0); } }\n            @keyframes slideLeft { from { transform: translateX(100%); } to { transform: translateX(0); } }\n        `;\n        document.head.appendChild(styleTag);\n\n        // 移动端和桌面端不同的样式\n        if (isMobile) {\n          Object.assign(container.style, {\n            position: \"fixed\",\n            bottom: \"0\",\n            left: \"0\",\n            right: \"0\",\n            width: \"100%\",\n            maxHeight: \"85vh\",\n            background: styles.bg,\n            borderTop: `1px solid ${styles.border}`,\n            borderTopLeftRadius: \"12px\",\n            borderTopRightRadius: \"12px\",\n            boxShadow: \"0 -4px 20px rgba(0,0,0,0.15)\",\n            fontSize: \"14px\",\n            display: \"none\",\n            flexDirection: \"column\",\n            zIndex: 99999,\n            overflow: \"hidden\",\n            fontFamily: \"-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif\",\n            animation: \"slideUp 0.3s cubic-bezier(0.16, 1, 0.3, 1)\"\n          });\n        } else {\n          Object.assign(container.style, {\n            position: \"fixed\",\n            top: \"0\",\n            right: \"0\",\n            width: \"380px\", // 更宽一点\n            height: \"100vh\", // 全高\n            background: styles.bg,\n            borderLeft: `1px solid ${styles.border}`,\n            boxShadow: \"-2px 0 12px rgba(0,0,0,0.05)\",\n            fontSize: \"14px\",\n            display: \"none\",\n            flexDirection: \"column\",\n            zIndex: 99999,\n            overflow: \"hidden\",\n            fontFamily: \"-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif\",\n            animation: \"slideLeft 0.3s cubic-bezier(0.16, 1, 0.3, 1)\"\n          });\n        }\n\n        // 顶部栏\n        const header = document.createElement(\"div\");\n        Object.assign(header.style, {\n          display: \"flex\",\n          justifyContent: \"space-between\",\n          alignItems: \"center\",\n          padding: \"12px 16px\",\n          borderBottom: `1px solid ${styles.border}`,\n          background: styles.cardBg,\n          color: styles.text,\n          flexShrink: 0\n        });\n        \n        const titleWrapper = document.createElement(\"div\");\n        titleWrapper.style.display = \"flex\";\n        titleWrapper.style.alignItems = \"center\";\n        titleWrapper.style.gap = \"8px\";\n        \n        const titleIcon = document.createElement(\"span\");\n        titleIcon.innerHTML = \"📝\"; // 图标\n        \n        const title = document.createElement(\"span\");\n        title.textContent = \"Annotations\";\n        title.style.fontWeight = \"600\";\n        title.style.fontSize = \"15px\";\n        \n        // 评论数量显示\n        const countSpan = document.createElement(\"span\");\n        countSpan.className = \"na-comment-header-count\";\n        Object.assign(countSpan.style, {\n            background: \"#eee\",\n            color: \"#666\",\n            padding: \"2px 8px\",\n            borderRadius: \"10px\",\n            fontSize: \"12px\",\n            fontWeight: \"500\"\n        });\n        \n        titleWrapper.append(titleIcon, title, countSpan);\n        header.appendChild(titleWrapper);\n        \n        // 关闭按钮\n        const closeBtn = document.createElement(\"button\");\n        closeBtn.innerHTML = `<svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"></line><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"></line></svg>`;\n        Object.assign(closeBtn.style, {\n          background: \"transparent\",\n          border: \"none\",\n          cursor: \"pointer\",\n          color: \"#999\",\n          padding: \"4px\",\n          display: \"flex\",\n          borderRadius: \"4px\",\n          transition: \"background 0.2s\"\n        });\n        closeBtn.onmouseenter = () => closeBtn.style.background = \"#f0f0f0\";\n        closeBtn.onmouseleave = () => closeBtn.style.background = \"transparent\";\n        closeBtn.onclick = function () {\n          container.style.display = \"none\";\n          overlay.style.display = \"none\";\n          if (isMobile) document.body.style.overflow = \"\";\n          \n          if (currentParaIndex !== null && paras[currentParaIndex]) {\n              paras[currentParaIndex].style.textDecoration = \"none\";\n              paras[currentParaIndex].style.background = \"transparent\";\n              currentParaIndex = null;\n              updateCommentCounts();\n          }\n        };\n        header.appendChild(closeBtn);\n\n        // 列表区域\n        const list = document.createElement(\"div\");\n        Object.assign(list.style, {\n          padding: \"16px\",\n          flex: \"1\",\n          overflowY: \"auto\",\n          background: \"#f7f7f7\", // 灰色背景\n          display: \"flex\",\n          flexDirection: \"column\",\n          gap: \"12px\" // 卡片间距\n        });\n\n        // 输入区域\n        const inputArea = document.createElement(\"div\");\n        Object.assign(inputArea.style, {\n          padding: \"16px\",\n          borderTop: `1px solid ${styles.border}`,\n          background: styles.cardBg,\n          flexShrink: 0\n        });\n\n        const textarea = document.createElement(\"textarea\");\n        textarea.placeholder = \"添加评论...\";\n        Object.assign(textarea.style, {\n          width: \"100%\",\n          minHeight: \"80px\",\n          boxSizing: \"border-box\",\n          padding: \"12px\",\n          border: `1px solid ${styles.border}`,\n          borderRadius: \"6px\",\n          fontSize: \"14px\",\n          fontFamily: \"inherit\",\n          resize: \"vertical\",\n          outline: \"none\",\n          transition: \"border-color 0.2s, box-shadow 0.2s\",\n          marginBottom: \"10px\",\n          userSelect: \"text\",\n          WebkitUserSelect: \"text\"\n        });\n        textarea.onfocus = () => {\n            textarea.style.borderColor = styles.primary;\n            textarea.style.boxShadow = `0 0 0 2px rgba(189, 28, 43, 0.1)`;\n        };\n        textarea.onblur = () => {\n            textarea.style.borderColor = styles.border;\n            textarea.style.boxShadow = \"none\";\n        };\n\n        const btnRow = document.createElement(\"div\");\n        btnRow.style.display = \"flex\";\n        btnRow.style.justifyContent = \"flex-end\";\n\n        const btn = document.createElement(\"button\");\n        btn.textContent = \"发布\";\n        Object.assign(btn.style, {\n          padding: \"8px 20px\",\n          border: \"none\",\n          background: styles.primary,\n          color: \"#fff\",\n          cursor: \"pointer\",\n          borderRadius: \"20px\", // 圆角按钮\n          fontSize: \"14px\",\n          fontWeight: \"600\",\n          transition: \"opacity 0.2s\",\n          boxShadow: \"0 2px 4px rgba(189, 28, 43, 0.3)\"\n        });\n        btn.onmouseenter = () => btn.style.opacity = \"0.9\";\n        btn.onmouseleave = () => btn.style.opacity = \"1\";\n\n        btn.onclick = async function () {\n          const content = textarea.value.trim();\n          if (!content || currentParaIndex == null) return;\n          \n          // 获取当前段落的上下文指纹 (前32个字符)\n          const pText = paras[currentParaIndex] ? getParaText(paras[currentParaIndex]) : \"\";\n          const contextText = pText.slice(0, 32);\n\n          try {\n            btn.textContent = \"发送中...\";\n            btn.disabled = true;\n\n            await apiPost(apiBase + \"/api/v1/comments\", {\n              siteId,\n              workId,\n              chapterId,\n              paraIndex: currentParaIndex,\n              content,\n              contextText,\n            });\n            textarea.value = \"\";\n            await loadAllComments();\n            updateCommentCounts();\n            await loadComments(currentParaIndex, list, sidebar.headerCount);\n          } catch (e) {\n            console.error(\"post comment failed\", e);\n            alert(\"发送失败\");\n          } finally {\n            btn.textContent = \"发布\";\n            btn.disabled = false;\n          }\n        };\n        \n        btnRow.appendChild(btn);\n        inputArea.append(textarea, btnRow);\n        \n        container.append(header, list, inputArea);\n        return { container, list, headerCount: countSpan };\n      }\n\n      // Helper to get pure text content excluding the badge\n      function getParaText(p) {\n          if (!p) return \"\";\n          // Clone to not modify DOM\n          const clone = p.cloneNode(true);\n          const badge = clone.querySelector(\".na-comment-count\");\n          if (badge) badge.remove();\n          return clone.textContent.trim();\n      }\n\n      // 缓存所有段落的评论数据\n      let allCommentsData = null;\n\n      // 模糊定位算法：将评论重新挂载到正确的段落\n      function reanchorComments(serverData) {\n          const correctedData = {};\n          const allComments = [];\n          \n          // 1. 扁平化所有评论\n          Object.values(serverData).forEach(list => allComments.push(...list));\n          \n          // 2. 重新分配\n          allComments.forEach(c => {\n              let targetIndex = c.paraIndex;\n              \n              // 检查是否需要重定位\n              // 如果有上下文指纹，且当前位置的内容不匹配，则搜索全篇\n              if (c.contextText) {\n                  const currentText = getParaText(paras[targetIndex]);\n                  \n                  // 如果当前段落不存在，或者开头不匹配，说明段落变动了\n                  if (!currentText.startsWith(c.contextText)) {\n                      // 简单的全篇搜索 (Fuzzy Search)\n                      // 优化：先搜索附近，再搜索全篇。这里简化为直接搜索全篇。\n                      let bestMatchIndex = -1;\n                      \n                      for (let i = 0; i < paras.length; i++) {\n                          const pText = getParaText(paras[i]);\n                          if (pText.startsWith(c.contextText)) {\n                              bestMatchIndex = i;\n                              break; // 找到了！\n                          }\n                      }\n                      \n                      if (bestMatchIndex !== -1) {\n                          targetIndex = bestMatchIndex;\n                          // console.log(`Re-anchored comment ${c.id} from ${c.paraIndex} to ${targetIndex}`);\n                      } else {\n                          // 如果找不到匹配的段落，就变成\"孤儿评论\"，或者保留在原位(虽然错位)\n                          // 这里选择保留在原位，或者放到第0段，或者标记为失效。\n                          // 为了体验，暂且保留原位，标红？不，还是原位吧。\n                      }\n                  }\n              }\n              \n              const key = String(targetIndex);\n              if (!correctedData[key]) correctedData[key] = [];\n              correctedData[key].push(c);\n          });\n          \n          return correctedData;\n      }\n\n      async function loadAllComments() {\n        try {\n          const url =\n            apiBase +\n            \"/api/v1/comments?siteId=\" +\n            encodeURIComponent(siteId) +\n            \"&workId=\" +\n            encodeURIComponent(workId) +\n            \"&chapterId=\" +\n            encodeURIComponent(chapterId);\n          const data = await apiGet(url);\n          \n          // 执行模糊定位纠正\n          allCommentsData = reanchorComments(data.commentsByPara || {});\n          return allCommentsData;\n        } catch (e) {\n          console.error(\"load comments failed\", e);\n          return {};\n        }\n      }\n\n      // 简单的 JWT 解析函数\n      function parseJwt(token) {\n        try {\n          const base64Url = token.split('.')[1];\n          const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');\n          const jsonPayload = decodeURIComponent(window.atob(base64).split('').map(function(c) {\n              return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2);\n          }).join(''));\n          return JSON.parse(jsonPayload);\n        } catch (e) {\n          return null;\n        }\n      }\n\n      async function loadComments(paraIndex, listEl, headerCountEl) {\n        const arr = (allCommentsData || {})[String(paraIndex)] || [];\n\n        listEl.innerHTML = \"\";\n        \n        // 检查当前用户权限\n        let isAdmin = false;\n        let isAuthor = false;\n        let token = null;\n        let editToken = null;\n        let currentUserId = null;\n        \n        if (typeof window !== \"undefined\" && window.PARANOTE_TOKEN) {\n          token = window.PARANOTE_TOKEN;\n          const payload = parseJwt(token);\n          if (payload) {\n            currentUserId = payload.sub || payload.userId;\n            if (payload.role === 'admin' || payload.isAdmin === true) {\n              isAdmin = true;\n            }\n          }\n        }\n        \n        // 检查是否是文章作者（支持多种方式：TAPNOTE_EDIT_TOKEN 或 PARANOTE_EDIT_TOKEN 或 data-edit-token）\n        if (typeof window !== \"undefined\") {\n          editToken = window.TAPNOTE_EDIT_TOKEN || window.PARANOTE_EDIT_TOKEN || script.dataset.editToken;\n          if (editToken) {\n            isAuthor = true;\n          }\n        }\n        \n        // 获取黑名单（管理员或作者可见）\n        let bannedUserIds = new Set();\n        if (isAdmin || isAuthor) {\n          try {\n            const headers = {};\n            if (token) headers[\"X-Paranote-Token\"] = token;\n            const banRes = await apiRequest(apiBase + `/api/v1/ban?siteId=${encodeURIComponent(siteId)}`, { headers });\n            if (banRes.bannedUsers) {\n              bannedUserIds = new Set(banRes.bannedUsers.map(b => b.userId));\n            }\n          } catch (e) {\n            console.warn(\"ParaNote: Failed to load banlist\", e);\n          }\n        }\n        \n        // 更新头部评论数\n        if (headerCountEl) {\n          headerCountEl.textContent = arr.length > 0 ? arr.length + \"条\" : \"\";\n        }\n        \n        if (!arr.length) {\n          const empty = document.createElement(\"div\");\n          empty.style.cssText = \"padding: 60px 20px; text-align: center; color: #999; font-size: 13px; background: #fff;\";\n          empty.innerHTML = '<div style=\"margin-bottom: 8px; font-size: 32px; opacity: 0.5;\">💬</div><div>还没有人发表评论</div>';\n          listEl.appendChild(empty);\n          return;\n        }\n        \n        arr.forEach(function (c, idx) {\n          const item = document.createElement(\"div\");\n          item.className = \"na-comment-card\";\n          Object.assign(item.style, {\n            padding: \"12px\",\n            marginBottom: \"0\", // gap 由父容器控制\n            background: \"#fff\",\n            borderRadius: \"8px\",\n            border: \"1px solid #eee\",\n            boxShadow: \"0 1px 3px rgba(0,0,0,0.05)\",\n            transition: \"transform 0.2s, box-shadow 0.2s\",\n            position: \"relative\"\n          });\n          \n          if (!isMobile) {\n              item.addEventListener(\"mouseenter\", () => {\n                  item.style.transform = \"translateY(-1px)\";\n                  item.style.boxShadow = \"0 4px 8px rgba(0,0,0,0.08)\";\n              });\n              item.addEventListener(\"mouseleave\", () => {\n                  item.style.transform = \"none\";\n                  item.style.boxShadow = \"0 1px 3px rgba(0,0,0,0.05)\";\n              });\n          }\n          \n          // 用户信息行\n          const userRow = document.createElement(\"div\");\n          userRow.style.cssText = \"display: flex; align-items: center; margin-bottom: 8px;\";\n          \n          // 用户头像 (多彩)\n          const avatar = document.createElement(\"div\");\n          const name = c.userName || c.userId || \"匿名\";\n          const firstChar = name.length > 0 ? name.charAt(0).toUpperCase() : \"?\";\n          \n          // 根据名字生成固定颜色\n          let hash = 0;\n          for (let i = 0; i < name.length; i++) hash = name.charCodeAt(i) + ((hash << 5) - hash);\n          const hue = hash % 360;\n          \n          avatar.style.cssText = `\n            width: 32px;\n            height: 32px;\n            border-radius: 50%;\n            background: hsl(${hue}, 60%, 85%);\n            color: hsl(${hue}, 60%, 30%);\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            font-weight: 600;\n            font-size: 14px;\n            margin-right: 10px;\n            flex-shrink: 0;\n            border: 1px solid rgba(0,0,0,0.05);\n          `;\n          avatar.textContent = firstChar;\n          \n          const userInfo = document.createElement(\"div\");\n          userInfo.style.cssText = \"flex: 1; min-width: 0; display: flex; flex-direction: column;\";\n          \n          const userName = document.createElement(\"span\");\n          userName.style.cssText = \"font-weight: 600; color: #333; font-size: 13px; display: flex; align-items: center; gap: 6px;\";\n          \n          // 用户名文本\n          const nameText = document.createElement(\"span\");\n          nameText.textContent = name;\n          userName.appendChild(nameText);\n          \n          // 已拉黑标记（管理员/作者可见）\n          const isUserBanned = c.userId && bannedUserIds.has(c.userId);\n          if ((isAdmin || isAuthor) && isUserBanned) {\n            const bannedBadge = document.createElement(\"span\");\n            bannedBadge.textContent = \"已拉黑\";\n            bannedBadge.style.cssText = \"font-size: 10px; color: #fff; background: #bd1c2b; padding: 1px 6px; border-radius: 10px; font-weight: 500;\";\n            userName.appendChild(bannedBadge);\n          }\n          \n          const meta = document.createElement(\"span\");\n          meta.style.cssText = \"font-size: 11px; color: #999; margin-top: 2px;\";\n          const date = c.createdAt ? new Date(c.createdAt).toLocaleString(\"zh-CN\", {\n            month: \"short\", day: \"numeric\", hour: \"2-digit\", minute: \"2-digit\"\n          }) : \"\";\n          meta.textContent = date;\n          \n          userInfo.appendChild(userName);\n          userInfo.appendChild(meta);\n          userRow.appendChild(avatar);\n          userRow.appendChild(userInfo);\n          \n          // 评论内容\n          const content = document.createElement(\"div\");\n          content.style.cssText = \"color: #444; font-size: 14px; line-height: 1.6; word-break: break-word; padding-left: 42px;\";\n          \n          // 处理引用内容 (简单markdown blockquote)\n          let contentText = c.content || '';\n          const MAX_LENGTH = 150; // 超过150字符折叠\n          \n          // 创建可折叠的内容显示\n          function createCollapsibleContent(text, container) {\n              if (text.length > MAX_LENGTH) {\n                  const shortText = text.slice(0, MAX_LENGTH) + '...';\n                  const textNode = document.createElement('span');\n                  textNode.textContent = shortText;\n                  \n                  const expandBtn = document.createElement('span');\n                  expandBtn.textContent = ' 展开';\n                  expandBtn.style.cssText = 'color:#bd1c2b;cursor:pointer;font-size:12px;margin-left:4px;';\n                  \n                  let expanded = false;\n                  expandBtn.onclick = (e) => {\n                      e.stopPropagation();\n                      expanded = !expanded;\n                      textNode.textContent = expanded ? text : shortText;\n                      expandBtn.textContent = expanded ? ' 收起' : ' 展开';\n                  };\n                  \n                  container.appendChild(textNode);\n                  container.appendChild(expandBtn);\n              } else {\n                  container.textContent = text;\n              }\n          }\n          \n          if (contentText.startsWith(\"> \")) {\n              const parts = contentText.split(\"\\n\");\n              const quoteText = parts[0].substring(2);\n              const mainText = parts.slice(1).join(\"\\n\").trim();\n              \n              const blockquote = document.createElement(\"div\");\n              blockquote.style.cssText = \"border-left: 3px solid #bd1c2b; padding-left: 8px; color: #777; margin-bottom: 6px; font-size: 13px; background: #f9f9f9; padding: 4px 8px; border-radius: 0 4px 4px 0;\";\n              blockquote.textContent = quoteText;\n              content.appendChild(blockquote);\n              \n              const p = document.createElement(\"div\");\n              createCollapsibleContent(mainText, p);\n              content.appendChild(p);\n          } else {\n              createCollapsibleContent(contentText, content);\n          }\n          \n          // 操作栏（回复 + 点赞 + 删除）\n          const actionContainer = document.createElement(\"div\");\n          actionContainer.style.cssText = \"display: flex; justify-content: flex-end; align-items: center; margin-top: 8px; padding-left: 42px; gap: 8px;\";\n          \n          // 回复按钮\n          const replyBtn = document.createElement(\"button\");\n          replyBtn.innerHTML = \"💬 回复\";\n          replyBtn.style.cssText = \"border:none; background:transparent; cursor:pointer; color:#666; font-size:12px; transition:color 0.2s;\";\n          replyBtn.onmouseenter = () => replyBtn.style.color = \"#bd1c2b\";\n          replyBtn.onmouseleave = () => replyBtn.style.color = \"#666\";\n          replyBtn.onclick = function(e) {\n            e.stopPropagation();\n            showReplyInput(item, c, paraIndex, listEl, headerCountEl);\n          };\n          actionContainer.appendChild(replyBtn);\n          \n          // 删除按钮（管理员或作者都可以删除）\n          if (isAdmin || isAuthor) {\n            const delBtn = document.createElement(\"button\");\n            delBtn.innerHTML = \"🗑️\";\n            delBtn.title = isAuthor ? \"删除（作者）\" : \"删除（管理员）\";\n            delBtn.style.cssText = \"border:none; background:transparent; cursor:pointer; color:#aaa; font-size:14px; transition:color 0.2s;\";\n            delBtn.onmouseenter = () => delBtn.style.color = \"#bd1c2b\";\n            delBtn.onmouseleave = () => delBtn.style.color = \"#aaa\";\n            delBtn.onclick = async function(e) {\n              e.stopPropagation();\n              if(!confirm(\"确定删除这条评论吗？\")) return;\n              try {\n                 const deleteData = { siteId, workId, chapterId, commentId: c.id };\n                 if (editToken) {\n                   deleteData.editToken = editToken;\n                 }\n                 \n                 const result = await apiDelete(apiBase + \"/api/v1/comments\", deleteData);\n                 if (!result.error) {\n                     await loadAllComments();\n                     updateCommentCounts();\n                     await loadComments(paraIndex, listEl, headerCountEl);\n                 } else {\n                     alert(result.error || \"删除失败\");\n                 }\n              } catch(e) { \n                 console.error(e);\n                 alert(\"删除失败\");\n              }\n            };\n            actionContainer.appendChild(delBtn);\n            \n            // 拉黑/解除拉黑按钮（管理员或作者可见，且不能拉黑自己）\n            if ((isAdmin || isAuthor) && c.userId && c.userId !== currentUserId) {\n              const banBtn = document.createElement(\"button\");\n              let isBanned = isUserBanned;\n              \n              // 更新按钮状态\n              function updateBanBtnState() {\n                if (isBanned) {\n                  banBtn.innerHTML = \"✅\";\n                  banBtn.title = \"解除拉黑\";\n                  banBtn.style.color = \"#52c41a\";\n                } else {\n                  banBtn.innerHTML = \"🚫\";\n                  banBtn.title = \"拉黑此用户\";\n                  banBtn.style.color = \"#aaa\";\n                }\n              }\n              \n              banBtn.style.cssText = \"border:none; background:transparent; cursor:pointer; font-size:14px; transition:color 0.2s;\";\n              updateBanBtnState();\n              \n              banBtn.onmouseenter = () => banBtn.style.opacity = \"0.7\";\n              banBtn.onmouseleave = () => banBtn.style.opacity = \"1\";\n              \n              banBtn.onclick = async function(e) {\n                e.stopPropagation();\n                const headers = { \"Content-Type\": \"application/json\" };\n                if (window.PARANOTE_TOKEN) {\n                  headers[\"X-Paranote-Token\"] = window.PARANOTE_TOKEN;\n                }\n                \n                try {\n                  if (isBanned) {\n                    // 解除拉黑\n                    if (!confirm(`确定解除拉黑用户 \"${c.userName || c.userId}\" 吗？`)) return;\n                    const result = await apiRequest(apiBase + \"/api/v1/ban\", {\n                      method: \"DELETE\",\n                      headers,\n                      body: JSON.stringify({ siteId, targetUserId: c.userId })\n                    });\n                    if (result.success) {\n                      isBanned = false;\n                      bannedUserIds.delete(c.userId);\n                      updateBanBtnState();\n                      // 移除已拉黑标记\n                      const badge = userName.querySelector('span:last-child');\n                      if (badge && badge.textContent === '已拉黑') badge.remove();\n                      alert(`已解除拉黑 \"${c.userName || c.userId}\"`);\n                    } else {\n                      alert(result.error || \"解除拉黑失败\");\n                    }\n                  } else {\n                    // 拉黑\n                    const reason = prompt(`确定拉黑用户 \"${c.userName || c.userId}\" 吗？\\n请输入拉黑原因（可选）：`);\n                    if (reason === null) return;\n                    const result = await apiRequest(apiBase + \"/api/v1/ban\", {\n                      method: \"POST\",\n                      headers,\n                      body: JSON.stringify({ siteId, targetUserId: c.userId, reason: reason || \"管理员拉黑\" })\n                    });\n                    if (result.success) {\n                      isBanned = true;\n                      bannedUserIds.add(c.userId);\n                      updateBanBtnState();\n                      // 添加已拉黑标记\n                      const bannedBadge = document.createElement(\"span\");\n                      bannedBadge.textContent = \"已拉黑\";\n                      bannedBadge.style.cssText = \"font-size: 10px; color: #fff; background: #bd1c2b; padding: 1px 6px; border-radius: 10px; font-weight: 500;\";\n                      userName.appendChild(bannedBadge);\n                      alert(`用户 \"${c.userName || c.userId}\" 已被拉黑`);\n                    } else {\n                      alert(result.error || \"拉黑失败\");\n                    }\n                  }\n                } catch(e) { \n                  console.error(e);\n                  alert(isBanned ? \"解除拉黑失败\" : \"拉黑失败\");\n                }\n              };\n              actionContainer.appendChild(banBtn);\n            }\n          }\n          \n          // 点赞按钮\n          const likeBtn = document.createElement(\"button\");\n          const likes = c.likes || 0;\n          likeBtn.innerHTML = `<span style=\"font-size:14px\">❤️</span> <span style=\"margin-left:4px; font-size:12px;\">${likes || ''}</span>`;\n          likeBtn.style.cssText = \"border:none; background:transparent; cursor:pointer; color:#aaa; display:flex; align-items:center; padding: 2px 6px; transition:color 0.2s; border-radius:4px;\";\n          \n          likeBtn.onmouseenter = () => { likeBtn.style.color = \"#bd1c2b\"; likeBtn.style.background = \"#fff0f0\"; };\n          likeBtn.onmouseleave = () => { likeBtn.style.color = \"#aaa\"; likeBtn.style.background = \"transparent\"; };\n\n          likeBtn.onclick = async function(e) {\n              e.stopPropagation();\n              try {\n                 const data = await apiPost(apiBase + \"/api/v1/comments/like\", { siteId, workId, chapterId, commentId: c.id });\n                 \n                 if (data.error === 'already_liked') return alert(\"您已经点过赞了\");\n                 if (data.error) return alert(data.error);\n\n                 if (data.likes !== undefined) {\n                     likeBtn.innerHTML = `<span style=\"font-size:14px\">❤️</span> <span style=\"margin-left:4px; font-weight:bold; color:#bd1c2b\">${data.likes}</span>`;\n                     likeBtn.style.color = \"#bd1c2b\";\n                 }\n              } catch(e) { console.error(e); }\n          };\n\n          actionContainer.appendChild(likeBtn);\n          \n          item.appendChild(userRow);\n          item.appendChild(content);\n          item.appendChild(actionContainer);\n          \n          // 显示回复（如果有，超过2条折叠）\n          if (c.replies && c.replies.length > 0) {\n            const repliesContainer = document.createElement(\"div\");\n            repliesContainer.style.cssText = \"margin-top: 12px; padding-left: 42px; border-left: 2px solid #eee;\";\n            \n            const MAX_VISIBLE_REPLIES = 2;\n            const replies = c.replies;\n            \n            if (replies.length > MAX_VISIBLE_REPLIES) {\n              // 先显示前2条\n              replies.slice(0, MAX_VISIBLE_REPLIES).forEach(reply => {\n                const replyItem = createReplyItem(reply, paraIndex, listEl, headerCountEl, isAdmin, isAuthor, token, editToken);\n                repliesContainer.appendChild(replyItem);\n              });\n              \n              // 隐藏的回复容器\n              const hiddenReplies = document.createElement(\"div\");\n              hiddenReplies.style.display = \"none\";\n              replies.slice(MAX_VISIBLE_REPLIES).forEach(reply => {\n                const replyItem = createReplyItem(reply, paraIndex, listEl, headerCountEl, isAdmin, isAuthor, token, editToken);\n                hiddenReplies.appendChild(replyItem);\n              });\n              repliesContainer.appendChild(hiddenReplies);\n              \n              // 展开/收起按钮\n              const toggleBtn = document.createElement(\"div\");\n              toggleBtn.style.cssText = \"color:#bd1c2b;font-size:12px;cursor:pointer;padding:8px 0;\";\n              toggleBtn.textContent = `展开 ${replies.length - MAX_VISIBLE_REPLIES} 条回复 ▼`;\n              toggleBtn.onclick = (e) => {\n                e.stopPropagation();\n                if (hiddenReplies.style.display === \"none\") {\n                  hiddenReplies.style.display = \"block\";\n                  toggleBtn.textContent = \"收起回复 ▲\";\n                } else {\n                  hiddenReplies.style.display = \"none\";\n                  toggleBtn.textContent = `展开 ${replies.length - MAX_VISIBLE_REPLIES} 条回复 ▼`;\n                }\n              };\n              repliesContainer.appendChild(toggleBtn);\n            } else {\n              replies.forEach(reply => {\n                const replyItem = createReplyItem(reply, paraIndex, listEl, headerCountEl, isAdmin, isAuthor, token, editToken);\n                repliesContainer.appendChild(replyItem);\n              });\n            }\n            \n            item.appendChild(repliesContainer);\n          }\n          \n          listEl.appendChild(item);\n        });\n      }\n      \n      // 创建回复项\n      function createReplyItem(reply, paraIndex, listEl, headerCountEl, isAdmin, isAuthor, token, editToken) {\n        const item = document.createElement(\"div\");\n        item.style.cssText = \"padding: 8px 0; border-bottom: 1px solid #f5f5f5;\";\n        \n        const name = reply.userName || reply.userId || \"匿名\";\n        let hash = 0;\n        for (let i = 0; i < name.length; i++) hash = name.charCodeAt(i) + ((hash << 5) - hash);\n        const hue = hash % 360;\n        \n        const header = document.createElement(\"div\");\n        header.style.cssText = \"display: flex; align-items: center; margin-bottom: 4px;\";\n        \n        const avatar = document.createElement(\"span\");\n        avatar.style.cssText = `width: 20px; height: 20px; border-radius: 50%; background: hsl(${hue}, 60%, 85%); color: hsl(${hue}, 60%, 30%); display: inline-flex; align-items: center; justify-content: center; font-size: 10px; font-weight: 600; margin-right: 6px;`;\n        avatar.textContent = name.charAt(0).toUpperCase();\n        \n        const userName = document.createElement(\"span\");\n        userName.style.cssText = \"font-size: 12px; font-weight: 600; color: #555;\";\n        userName.textContent = name;\n        \n        const time = document.createElement(\"span\");\n        time.style.cssText = \"font-size: 10px; color: #999; margin-left: 8px;\";\n        time.textContent = reply.createdAt ? new Date(reply.createdAt).toLocaleString(\"zh-CN\", { month: \"short\", day: \"numeric\", hour: \"2-digit\", minute: \"2-digit\" }) : \"\";\n        \n        header.append(avatar, userName, time);\n        \n        const content = document.createElement(\"div\");\n        content.style.cssText = \"font-size: 13px; color: #555; line-height: 1.5; padding-left: 26px;\";\n        content.textContent = reply.content;\n        \n        item.append(header, content);\n        \n        // 递归显示嵌套回复\n        if (reply.replies && reply.replies.length > 0) {\n          const nested = document.createElement(\"div\");\n          nested.style.cssText = \"margin-left: 26px; margin-top: 8px;\";\n          reply.replies.forEach(r => {\n            nested.appendChild(createReplyItem(r, paraIndex, listEl, headerCountEl, isAdmin, isAuthor, token, editToken));\n          });\n          item.appendChild(nested);\n        }\n        \n        return item;\n      }\n      \n      // 显示回复输入框\n      function showReplyInput(parentItem, parentComment, paraIndex, listEl, headerCountEl) {\n        // 移除已有的回复框\n        const existing = parentItem.querySelector(\".reply-input-box\");\n        if (existing) {\n          existing.remove();\n          return;\n        }\n        \n        const box = document.createElement(\"div\");\n        box.className = \"reply-input-box\";\n        box.style.cssText = \"margin-top: 10px; padding: 10px; background: #f9f9f9; border-radius: 6px; margin-left: 42px;\";\n        \n        const textarea = document.createElement(\"textarea\");\n        textarea.placeholder = `回复 ${parentComment.userName || '匿名'}...`;\n        textarea.style.cssText = \"width: 100%; height: 60px; border: 1px solid #ddd; border-radius: 4px; padding: 8px; font-size: 13px; resize: none; box-sizing: border-box; user-select: text; -webkit-user-select: text;\";\n        \n        const btnRow = document.createElement(\"div\");\n        btnRow.style.cssText = \"display: flex; justify-content: flex-end; gap: 8px; margin-top: 8px;\";\n        \n        const cancelBtn = document.createElement(\"button\");\n        cancelBtn.textContent = \"取消\";\n        cancelBtn.style.cssText = \"padding: 6px 12px; border: 1px solid #ddd; background: #fff; border-radius: 4px; cursor: pointer; font-size: 12px;\";\n        cancelBtn.onclick = () => box.remove();\n        \n        const submitBtn = document.createElement(\"button\");\n        submitBtn.textContent = \"回复\";\n        submitBtn.style.cssText = \"padding: 6px 12px; border: none; background: #bd1c2b; color: #fff; border-radius: 4px; cursor: pointer; font-size: 12px;\";\n        submitBtn.onclick = async () => {\n          const content = textarea.value.trim();\n          if (!content) return;\n          \n          try {\n            submitBtn.textContent = \"发送中...\";\n            submitBtn.disabled = true;\n            \n            await apiPost(apiBase + \"/api/v1/comments\", {\n              siteId,\n              workId,\n              chapterId,\n              paraIndex,\n              content,\n              parentId: parentComment.id,\n            });\n            \n            box.remove();\n            await loadAllComments();\n            updateCommentCounts();\n            await loadComments(paraIndex, listEl, headerCountEl);\n          } catch (e) {\n            console.error(\"reply failed\", e);\n            alert(\"回复失败\");\n            submitBtn.textContent = \"回复\";\n            submitBtn.disabled = false;\n          }\n        };\n        \n        btnRow.append(cancelBtn, submitBtn);\n        box.append(textarea, btnRow);\n        parentItem.appendChild(box);\n        textarea.focus();\n      }\n\n      // 更新段落评论数显示\n      function updateCommentCounts() {\n        paras.forEach(function (p, idx) {\n          const count = (allCommentsData || {})[String(idx)]?.length || 0;\n          let badge = p.querySelector(\".na-comment-count\");\n          if (!badge) {\n            badge = document.createElement(\"span\");\n            badge.className = \"na-comment-count\";\n            p.appendChild(badge);\n          }\n\n          // 样式逻辑：默认为灰色，只有当前选中段落(currentParaIndex)才显示红色\n          const isActive = (currentParaIndex === idx);\n          \n          // 统一风格：全部显示数字，不再使用 emoji\n          // 未选中：灰色(#999)，选中：红色(#f56c6c)\n          const color = isActive ? \"#f56c6c\" : \"#999\";\n          const borderColor = isActive ? \"#f56c6c\" : \"#e0e0e0\"; // 平时边框淡一点\n          \n          Object.assign(badge.style, {\n            display: \"inline-block\",\n            marginLeft: isMobile ? \"8px\" : \"6px\",\n            padding: \"0 4px\",\n            fontSize: isMobile ? \"11px\" : \"10px\",\n            color: color,\n            background: \"#fff\",\n            border: `1px solid ${borderColor}`,\n            borderRadius: \"2px\",\n            cursor: \"pointer\",\n            fontWeight: \"500\",\n            minWidth: \"18px\",\n            height: \"18px\",\n            lineHeight: \"16px\", // adjust for border\n            textAlign: \"center\",\n            verticalAlign: \"middle\",\n            touchAction: \"manipulation\",\n            transition: \"all 0.15s ease\",\n            boxSizing: \"border-box\",\n          });\n          \n          badge.textContent = count;\n          badge.title = count + \" 条评论\";\n          \n          // 移除之前的特殊样式 override\n          badge.style.fontSize = isMobile ? \"11px\" : \"10px\";\n          \n          if (!isMobile) {\n            badge.onmouseenter = function () {\n              badge.style.borderColor = \"#f56c6c\";\n              badge.style.color = \"#f56c6c\";\n            };\n            badge.onmouseleave = function () {\n              badge.style.borderColor = borderColor;\n              badge.style.color = color;\n            };\n          }\n        });\n      }\n\n      // 为每个段落添加点击事件和评论数显示\n      paras.forEach(function (p, idx) {\n        p.dataset.naIndex = String(idx);\n        Object.assign(p.style, {\n          cursor: \"pointer\",\n          position: \"relative\",\n          padding: isMobile ? \"8px 0\" : \"4px 0\", // 移动端增大点击区域\n          borderRadius: \"4px\",\n          transition: \"all 0.2s\",\n          WebkitTapHighlightColor: \"transparent\", // 移除移动端点击高亮\n          touchAction: \"manipulation\", // 移动端优化触摸\n        });\n\n        // 桌面端 hover 效果（更柔和）\n        if (!isMobile) {\n          p.addEventListener(\"mouseenter\", function () {\n            if (currentParaIndex !== idx) {\n              p.style.background = \"rgba(0, 0, 0, 0.02)\";\n            }\n          });\n          p.addEventListener(\"mouseleave\", function () {\n            if (currentParaIndex !== idx) {\n              p.style.background = \"transparent\";\n              p.style.textDecoration = \"none\";\n            }\n          });\n        }\n\n        // 统一的点击/触摸处理\n        const handleClick = async function (e) {\n          // 如果点击的是链接或交互元素，优先处理原有行为，不触发评论\n          if (e.target.closest(\"a, button, input, textarea, select, [role='button']\")) return;\n\n          // 移除之前选中段落的下划线\n          if (currentParaIndex !== null && paras[currentParaIndex]) {\n            paras[currentParaIndex].style.textDecoration = \"none\";\n            paras[currentParaIndex].style.background = \"transparent\";\n          }\n\n          // 如果点击的是当前已经打开的段落，则执行关闭逻辑\n          if (currentParaIndex === idx && sidebar.container.style.display !== \"none\") {\n              currentParaIndex = null;\n              updateCommentCounts();\n              sidebar.container.style.display = \"none\";\n              if (isMobile) {\n                  overlay.style.display = \"none\";\n                  document.body.style.overflow = \"\";\n              }\n              return;\n          }\n          \n          // 给当前段落加下划线（起点风格：红色下划线）\n          currentParaIndex = idx;\n          p.style.textDecoration = \"underline\";\n          p.style.textDecorationColor = \"#f56c6c\";\n          p.style.textDecorationThickness = isMobile ? \"2px\" : \"1.5px\";\n          p.style.textUnderlineOffset = \"2px\";\n          p.style.background = \"transparent\";\n          \n          // 更新所有徽章样式（当前选中的变红）\n          updateCommentCounts();\n\n          // 显示侧边栏和遮罩\n          sidebar.container.style.display = \"flex\";\n          if (isMobile) {\n            overlay.style.display = \"block\";\n            document.body.style.overflow = \"hidden\";\n            // 移动端滚动到顶部\n            sidebar.container.scrollTop = 0;\n          }\n          await loadComments(idx, sidebar.list, sidebar.headerCount);\n        };\n\n        p.onclick = handleClick;\n        // 移动端也支持 touchstart（防止双击缩放）\n        if (isMobile) {\n          p.addEventListener(\"touchend\", function (e) {\n            // e.preventDefault(); // 保持默认行为以免影响选中\n            // handleClick(e);\n          }, { passive: false });\n        }\n      });\n\n      // 初始化：加载所有评论并更新计数\n      loadAllComments().then(function () {\n        updateCommentCounts();\n      });\n  } // End of init\n\n  init();\n\n})();\n" },
  "/js/admin.js": { type: "application/javascript; charset=utf-8", body: "// confirm-before-submit for admin forms\ndocument.addEventListener(\"DOMContentLoaded\", function () {\n  var forms = document.querySelectorAll(\"form[data-confirm]\");\n  forms.forEach(function (f) {\n    f.addEventListener(\"submit\", function (ev) {\n      var msg = f.getAttribute(\"data-confirm\") || \"Are you sure?\";\n      if (!window.confirm(msg)) ev.preventDefault();\n    });\n  });\n});\n" },
};
